def test_hyb_mgga_xc_pbe1kcis_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_pbe1kcis", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.405532770083592e+00, -3.341340642095721e+00, -3.251458395426651e+00, -3.127089218594592e+00, -2.957917174576840e+00, -2.733392393927841e+00, -2.445736417625089e+00, -2.095277739553144e+00, -1.697056594662343e+00, -1.280715539155709e+00, -8.708103680783753e-01, -5.933445143536555e-01, -5.109200339063041e-01, -4.173526604350162e-01, -3.050374157089848e-01, -1.965510862665057e-01, -1.058331880895910e-01, -3.883196759447044e-02, -8.437256637537777e-03, -9.486512687998839e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


